package io.knowledgebrain.integration;
import java.util.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import org.springframework.web.server.ResponseStatusException;
class GitHubRulesTest {
 @Test void onlyExplicitPublicGithubRepoPageSyntaxIsCanonicalized(){assertEquals("https://github.com/octocat/hello-world",GitHubRules.url("https://github.com/Octocat/Hello-World/"));assertEquals("https://github.com/a/repo.git",GitHubRules.url("https://github.com/a/repo.git"));for(String raw:List.of("http://github.com/a/b","https://api.github.com/a/b","https://github.com.evil.test/a/b","https://token@github.com/a/b","https://github.com:443/a/b","https://github.com/a/b?token=x","https://github.com/a/b#ref","https://github.com/a/b/tree/main","https://github.com/a/%2e%2e","https://github.com/a/..","https://127.0.0.1/a/b","https://github.com/-a/b"," https://github.com/a/b"))assertThrows(ResponseStatusException.class,()->GitHubRules.url(raw),raw);}
 @Test void domainIdsKeysAndShaAreBoundedAndNeverExternalIds(){assertEquals(7,GitHubRules.id("019a0000-0000-7000-8000-000000000001").version());assertThrows(ResponseStatusException.class,()->GitHubRules.id(UUID.randomUUID().toString()));assertThrows(ResponseStatusException.class,()->GitHubRules.key("x"));assertEquals("a".repeat(40),GitHubRules.sha("a".repeat(40)));assertEquals("b".repeat(64),GitHubRules.sha("b".repeat(64)));assertThrows(ResponseStatusException.class,()->GitHubRules.sha("A".repeat(40)));assertThrows(ResponseStatusException.class,()->GitHubRules.text("bad\ntext",100,true));}
}
